arguments.command:
cat << 'EOF' > /tmp/stackalloc_nint.cs
using System;

var span = (stackalloc nint[4]);
span[0] = 42;
span[1] = nint.MaxValue;
span[2] = nint.MinValue;
span[3] = (nint)123456789;

Console.WriteLine($"Length: {span.Length}");
for (int i = 0; i < span.Length; i++)
    Console.WriteLine($"  span[{i}] = {span[i]}");
Console.WriteLine($"nint size: {nint.Size} bytes");
EOF
dotnet run --project /tmp/stackalloc_nint.cs 2>&1 || dotnet-script /tmp/stackalloc_nint.cs 2>&1 || { cd /tmp && dotnet new console -o stackalloc_test --force -n StackallocTest && cp stackalloc_nint.cs stackalloc_test/Program.cs && dotnet run --project stackalloc_test; }

